import{_ as e,o as r,c as t,a2 as i}from"./chunks/framework.iXqqCa-C.js";const g=JSON.parse('{"title":"智能体常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"guide/agent/faq.md","filePath":"guide/agent/faq.md","lastUpdated":1793501934000}'),l={name:"guide/agent/faq.md"};function o(h,a,n,d,s,u){return r(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="智能体常见问题" tabindex="-1">智能体常见问题 <a class="header-anchor" href="#智能体常见问题" aria-label="Permalink to &quot;智能体常见问题&quot;">​</a></h1><p>智能体游玩和创作中的常见问题。429 限流、令牌泄露等站点问题见<a href="/guide/faq">常见问题</a>。</p><h2 id="提示「余额不足-无法发送」" tabindex="-1">提示「余额不足，无法发送」 <a class="header-anchor" href="#提示「余额不足-无法发送」" aria-label="Permalink to &quot;提示「余额不足，无法发送」&quot;">​</a></h2><p>额度不足。可以签到、兑换卡密，或切换到免费模型，见<a href="/guide/agent/usage#余额不足">用量与额度</a>。</p><h2 id="回复生成失败怎么办" tabindex="-1">回复生成失败怎么办 <a class="header-anchor" href="#回复生成失败怎么办" aria-label="Permalink to &quot;回复生成失败怎么办&quot;">​</a></h2><p>发送的内容会退回输入框，<strong>直接重试即可</strong>，失败的请求不计费。频繁失败时可以换一个模型，并在「模型」标签页点「上报异常」反馈给管理员。</p><h2 id="角色是不是忘了我们之前聊的" tabindex="-1">角色是不是忘了我们之前聊的？ <a class="header-anchor" href="#角色是不是忘了我们之前聊的" aria-label="Permalink to &quot;角色是不是忘了我们之前聊的？&quot;">​</a></h2><p>先看界面上有没有<a href="/guide/agent/chat#消息">上下文边界</a>。边界以上的消息不再原文发给模型，这是模型上下文长度的限制。让角色记住边界以外的内容：</p><ul><li>开启<a href="/guide/agent/memory">记忆</a>的便签压缩。</li><li>创作者可以把关键设定写进<a href="/guide/agent/worldbook">世界书</a>，命中时注入。</li></ul><h2 id="记忆开了但感觉没用" tabindex="-1">记忆开了但感觉没用 <a class="header-anchor" href="#记忆开了但感觉没用" aria-label="Permalink to &quot;记忆开了但感觉没用&quot;">​</a></h2><ul><li>便签只覆盖上下文边界以外的消息，边界内的消息本来就会原文发给模型。</li><li>在「记忆」页确认「长期记忆实现」选的是「便签压缩」。</li><li>查看便签列表是否在生成（状态为「生成中」或「参与回复」）。</li><li>记忆按会话隔离，换会话就是空白，不是丢档。</li></ul><h2 id="切换压缩模型后便签不见了" tabindex="-1">切换压缩模型后便签不见了 <a class="header-anchor" href="#切换压缩模型后便签不见了" aria-label="Permalink to &quot;切换压缩模型后便签不见了&quot;">​</a></h2><p>切换压缩模型会清空当前会话的便签并重新压缩，这是正常行为。</p><h2 id="删除会话会删掉什么" tabindex="-1">删除会话会删掉什么 <a class="header-anchor" href="#删除会话会删掉什么" aria-label="Permalink to &quot;删除会话会删掉什么&quot;">​</a></h2><p>消息记录和便签会<strong>一并删除且不可恢复</strong>，只保留模型调用记录。需要保留剧情时，先在「会话」标签页导出聊天记录。</p><h2 id="消息发不出去-提示先选择对话风格" tabindex="-1">消息发不出去，提示先选择对话风格 <a class="header-anchor" href="#消息发不出去-提示先选择对话风格" aria-label="Permalink to &quot;消息发不出去，提示先选择对话风格&quot;">​</a></h2><p>发送消息前必须为会话选择<a href="/guide/agent/styles">对话风格</a>。可以从广场加入一份，或自己创建。</p><h2 id="生图失败-图片没保存" tabindex="-1">生图失败 / 图片没保存 <a class="header-anchor" href="#生图失败-图片没保存" aria-label="Permalink to &quot;生图失败 / 图片没保存&quot;">​</a></h2><p>按提示原因处理：</p><ul><li><strong>内容审核拦截</strong>：不合规内容不会出图，需要调整对话内容。</li><li><strong>网盘空间不足</strong>：清理网盘后再试。</li><li><strong>文件类型不允许 / 超过大小限制</strong>：由账号的上传策略决定。</li><li><strong>额度不足</strong>：先补充额度。</li><li>部分图片指令超出每轮自动生成上限，需要手动点击生成。</li></ul><h2 id="角色表情包发不出来" tabindex="-1">角色表情包发不出来 <a class="header-anchor" href="#角色表情包发不出来" aria-label="Permalink to &quot;角色表情包发不出来&quot;">​</a></h2><p>排查顺序：站点是否启用了智能体表情包 → 每轮上限是否为 0（0 表示关闭）→ 全站表情是否由管理员填写了「智能体描述」。细节见<a href="/guide/agent/regex-stickers">正则与表情包</a>。</p><h2 id="我提交的角色没通过审核" tabindex="-1">我提交的角色没通过审核 <a class="header-anchor" href="#我提交的角色没通过审核" aria-label="Permalink to &quot;我提交的角色没通过审核&quot;">​</a></h2><p>未通过的作品会显示外审反馈的问题分类和原因，按反馈修改后重新提交即可。常见原因有露骨色情、越线的暴力描写和诱导性内容。见<a href="/guide/agent/create#测试与发布">创作角色</a>。</p><h2 id="会话或角色显示「已被封禁」" tabindex="-1">会话或角色显示「已被封禁」 <a class="header-anchor" href="#会话或角色显示「已被封禁」" aria-label="Permalink to &quot;会话或角色显示「已被封禁」&quot;">​</a></h2><p>这是管理员的处置，两种封禁的区别见<a href="/guide/agent/chat#对话中会遇到的状态">对话中会遇到的状态</a>。认为误判请<a href="/guide/faq#联系项目组">联系项目组</a>。</p><h2 id="测试会话和社区会话有什么区别" tabindex="-1">测试会话和社区会话有什么区别 <a class="header-anchor" href="#测试会话和社区会话有什么区别" aria-label="Permalink to &quot;测试会话和社区会话有什么区别&quot;">​</a></h2><p>草稿测试会话只有你自己可见，用来验证角色设定；社区会话是和已发布角色的对话。两者功能相同，见<a href="/guide/agent/quick-start#草稿测试与社区游玩">草稿测试与社区游玩</a>。</p><h2 id="怎么让角色用某种格式回复-表格、代码块" tabindex="-1">怎么让角色用某种格式回复（表格、代码块……） <a class="header-anchor" href="#怎么让角色用某种格式回复-表格、代码块" aria-label="Permalink to &quot;怎么让角色用某种格式回复（表格、代码块……）&quot;">​</a></h2><p>对话气泡支持 Markdown。创作者可以在人设、示例对话或风格说明里写明格式要求，用户也可以直接在消息里提出。语法见<a href="/guide/agent/syntax">对话语法</a>。</p>',30)])])}const f=e(l,[["render",o]]);export{g as __pageData,f as default};
